        return str(len(qs)) + '\n' + '\n'.join(f'{w} {x}' for w, x in qs)
    tests = [fmt([(8, 0)]), fmt([(8, 255)]), fmt([(32, 0)]), fmt([(32, 2**32 - 1)]), fmt([(8, 172), (8, 85), (8, 170)]),
             fmt([(32, 1), (32, 2), (32, 2**31), (32, 2**30)]), fmt([(8, 1), (8, 2), (8, 128), (8, 64)])]
    for _ in range(8):
        tests.append(fmt([(8, rng.randint(0, 255)) for _ in range(rng.randint(1, 15))]))
    for _ in range(5):
        tests.append(fmt([(rng.choice([8, 32]), 0) for _ in range(2)] + [(32, rng.randint(0, 2**32 - 1)) for _ in range(rng.randint(1, 6))]))
    def rnd():
        w = rng.choice([8, 32])
        return (w, rng.randint(0, 2**w - 1))
    tests.append(fmt([rnd() for _ in range(50000)]))
    tests.append(fmt([(32, rng.choice([0, 2**32 - 1, rng.randint(0, 2**32 - 1)])) for _ in range(50000)]))
    return tests

